def transform(grid):
    from collections import deque, Counter

    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    frame_cells = set()

    # Find connected components that form complete rectangular borders.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue

            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))

            r0 = min(x for x, y in comp)
            r1 = max(x for x, y in comp)
            c0 = min(y for x, y in comp)
            c1 = max(y for x, y in comp)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue

            perimeter = {
                (x, y)
                for x in range(r0, r1 + 1)
                for y in range(c0, c1 + 1)
                if x in (r0, r1) or y in (c0, c1)
            }
            if set(comp) == perimeter:
                frames.append((color, r0, r1, c0, c1, perimeter))
                frame_cells.update(perimeter)

    # Count the scattered colored markers, excluding the rectangle borders.
    counts = Counter(
        grid[r][c]
        for r in range(h)
        for c in range(w)
        if grid[r][c] != 0 and (r, c) not in frame_cells
    )

    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1, perimeter in frames:
        for r, c in perimeter:
            out[r][c] = color

        # Fill alternating cells with the marker color whose count matches
        # the number of cells in this checkerboard pattern.
        inside = [
            (r, c)
            for r in range(r0 + 1, r1)
            for c in range(c0 + 1, c1)
            if (r - r0 - 1 + c - c0 - 1) % 2 == 0
        ]
        for marker, count in counts.items():
            if count == len(inside):
                for r, c in inside:
                    out[r][c] = marker
                break

    return out
